<?php

namespace Bga\Games\RegroupChickenArmy\States;

use Bga\Games\RegroupChickenArmy\Components\Players;
use Bga\Games\RegroupChickenArmy\Components\Resources;
use Bga\Games\RegroupChickenArmy\Game;
use BgaUserException;
use BgaVisibleSystemException;

class GamePreparationStateHandler implements StateHandlerInterface
{
    /* AUTOGENERATED_HANDLE_START - DO NOT REMOVE THIS COMMENT */
    public static function handle(Game $game, string $action, ...$args): void
    {
        switch ($action) {

            default:
                throw new BgaVisibleSystemException("Invalid action: $action");
        }
    }
    /* AUTOGENERATED_HANDLE_END - DO NOT REMOVE THIS COMMENT */


    public static function executeGameState(Game $game): void
    {
        try {
            $leaderInherentResourcesEnabled = $game->getGameStateValue('leaderInherentResourcesEnabled');
            if ($leaderInherentResourcesEnabled == 1) {
                $game->trace("Leader inherent resources enabled, going to leader selection");
                $game->gamestate->nextState('leaderSelection');
                return;
            }
        } catch (\Throwable $ignore) {
            $game->trace("Error checking game options: " . $ignore->getMessage());
        };

        $game->trace("Skipping leader selection, randomly assigning leaders");

        $players = $game->getCollectionFromDB("SELECT player_id FROM player WHERE player_eliminated = 0 AND player_zombie = 0");

        $playerIds = array_map(function ($player) {
            return $player['player_id'];
        }, $players);

        $leaderIds = array_keys(Players::LEADER_ORDER);
        shuffle($playerIds);

        foreach ($playerIds as $playerId) {
            if (empty($leaderIds)) {
                break;
            }

            $leaderId = array_shift($leaderIds);
            $game->DbQuery(
                "INSERT IGNORE INTO playerData (player_id, is_first, has_attacked, has_healed, marketCardPicked, leader_id)
                 VALUES ($playerId, 0, 0, 0, 0, $leaderId)"
            );
            Players::assignPlayerToLeader($game, $playerId, $leaderId);

            Resources::initializeResources($game, $leaderId);
        }

        $game->gamestate->nextState('skipSelection');
    }
}
